def _parse_flat(raw: str):
    out = []
    for line in raw.strip().splitlines():
        p = [x.strip() for x in line.split("|")]
        if len(p) == 6:
            out.append((p[0], p[1:5], 0, p[5]))
    return out


def _parse_sections(raw: str):
    out, cur = {}, None
    for line in raw.strip().splitlines():
        line = line.strip()
        if line.startswith("#"):
            cur = line[1:]
            out[cur] = []
        elif cur and line.count("|") == 5:
            p = [x.strip() for x in line.split("|")]
            out[cur].append((p[0], p[1:5], 0, p[5]))
    return out


def _norm(s: str) -> str:
    return " ".join(s.lower().split())


def pick(src, idx):
    return [src[i] for i in idx]


