TOPIC_OF: dict[int, str] = {}     # id вопроса -> ключ темы


def add_topic(section: str, key: str, title: str, questions: list):
    POOLS[key] = questions
    TITLES[key] = title
    PARENT[key] = section
    CHILDREN.setdefault(section, []).append(key)
    for q in questions:
        TOPIC_OF.setdefault(id(q), key)


