def weak_info(uid: int) -> list:
    out = []
    for k, (c, t) in tstats.get(uid, {}).items():
        if t >= WEAK_MIN and c / t * 100 < WEAK_PCT:
            out.append((c / t, k, c, t))
    out.sort()
    return out


def draw(uid: int, key: str, n: int) -> list:
    if key == "exam":
        return [random.choice(POOLS[k]) for k in ALL_K]
    if key == "weak":
        pool = [q for _, k, _, _ in weak_info(uid)[:3] for q in POOLS[k]]
    else:
        pool = POOLS[key]
    return random.sample(pool, min(n, len(pool)))


_TOK: dict[str, frozenset] = {}


def _tok(x: str) -> frozenset:
    r = _TOK.get(x)
    if r is None:
        r = frozenset(w[:5] for w in re.findall(r"\w+", x.lower()) if len(w) > 2)
        _TOK[x] = r
    return r


def _jac(a, b) -> float:
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)


def _lensim(a: str, b: str) -> float:
    return 1 - abs(len(a) - len(b)) / max(len(a), len(b), 1)


