def _mutations(right: str) -> list:
    out = []
    # дроби
    for a, bs in (("1/2", ["2/3", "3/4"]), ("2/3", ["1/2", "3/4"]), ("3/4", ["2/3", "1/2"]), ("3/5", ["2/3", "1/2"])):
        if a in right:
            out += [right.replace(a, b, 1) for b in bs]
    # числа цифрами
    for m in re.finditer(r"(?<![\d/])(\d{1,4})(?![\d/])", right):
        n = int(m.group(1))
        if n >= 1000:
            continue
        before = right[max(0, m.start() - 8):m.start()].lower()
        if n >= 100 and ("ст" in before):                # номер статьи
            alts = [n + 1, n - 1]
        elif n >= 100:
            alts = [n // 2, n * 2] if n % 10 == 0 else [n + 10, n - 10]
        else:
            alts = sorted({3, 5, 6, 7, 10, 14, 15, 18, 30, 60} - {n}, key=lambda x: abs(x - n))[:2]
        out += [right[:m.start()] + str(x) + right[m.end():] for x in alts if x > 0]
        break
    # числа словами
    for w, alts in _NUMW.items():
        m = re.search(r"(?<!\w)" + w + r"(?!\w)", right, re.I)
        if m:
            for x in alts[:2]:
                x = x.capitalize() if m.group(0)[0].isupper() else x
                out.append(right[:m.start()] + x + right[m.end():])
            break
    # подмена понятий
    for a, b in _SWAPS:
        m = re.search(r"(?<!\w)" + re.escape(a) + r"(?!\w)", right)
        if m and b.lower() not in right.lower():
            out.append(right[:m.start()] + b + right[m.end():])
    # перечисления из 3+ пунктов: вариант с пропущенным пунктом
    parts = re.split(r",\s+| и ", right)
    if len(parts) >= 3 and len(right) < 160:
        for drop in (len(parts) - 1, 1):
            rest = [p for i, p in enumerate(parts) if i != drop]
            out.append(", ".join(rest[:-1]) + " и " + rest[-1])
    seen, res = set(), []
    for o in out:
        if o != right and o not in seen:
            seen.add(o)
            res.append(o)
    return res


def hard_options(t, n: int = 3) -> list:
    """Правильный ответ + n неверных, максимально похожих на него:
    вариации самого ответа (числа, дроби, подмена понятий), ответы и неверные варианты
    соседних вопросов той же темы, исходные неверные варианты."""
    text, options, correct, _ = t
    right = options[correct]
    topic = TOPIC_OF.get(id(t))
    pool = list(POOLS.get(topic, []))
    if topic and len(pool) < 30:
        have = {id(u) for u in pool}
        pool += [u for u in POOLS.get(PARENT.get(topic), []) if id(u) not in have]
    qt, rt, rl = _tok(text), _tok(right), right.lower()

    def score(o: str, qs: float) -> float:
        return 0.5 * min(_jac(rt, _tok(o)) / 0.5, 1.0) + 0.3 * _lensim(o, right) + 0.2 * qs

    def too_close(o: str) -> bool:
        ol = o.lower()
        return o == right or _jac(rt, _tok(o)) > 0.5 or ((ol in rl or rl in ol) and _lensim(o, right) > 0.5)

    cands: dict[str, float] = {}
    for k, o in enumerate(options):                       # исходные неверные — как резерв
        if k != correct:
            cands[o] = score(o, 1.0) * 0.9
    for o in _mutations(right):                           # близкие вариации верного ответа
        cands[o] = 1.0
    for u in pool:                                        # неверные варианты и ответы соседних вопросов
        if u is t:
            continue
        qs = _jac(qt, _tok(u[0]))
        if qs >= 0.9:                                     # вопрос того же вида: его ответ может быть тоже верным
            continue
        for k, o in enumerate(u[1]):
            if too_close(o) or _lensim(o, right) < 0.45:
                continue
            if k == u[2]:
                if qs < 0.5:                              # чужой верный ответ берём только у вопросов той же формы
                    continue
                w = 1.0
            else:
                if qs < 0.35:
                    continue
                w = 0.9
            sc = score(o, qs) * w
            if sc >= 0.4 and sc > cands.get(o, 0):
                cands[o] = sc
    out, muts = [], 0
    ml = set(_mutations(right))
    for o, _ in sorted(cands.items(), key=lambda x: -x[1]):
        if o == right or o in out:
            continue
        if o in ml:
            if muts >= 2:
                continue
            muts += 1
        out.append(o)
        if len(out) == n:
            break
    return [right] + out


def build(tuples, hard: bool = False) -> list:
    out = []
    for t in tuples:
        text, options, correct, expl = t
        sh = hard_options(t) if hard else options[:]
        right = sh[0] if hard else options[correct]
        random.shuffle(sh)
        out.append({"q": text, "opts": sh, "ans": sh.index(right), "expl": expl,
                    "hide": [], "orig": t, "topic": TOPIC_OF.get(id(t))})
    return out


def new_session(key: str, tuples, hard: bool = False) -> dict:
    return {"key": key, "qs": build(tuples, hard), "i": 0, "score": 0, "wrong": [], "fifty": FIFTY}


def head(s: dict) -> str:
    return f"{s['i'] + 1} / {len(s['qs'])}  ·  верно {s['score']}  ·  ошибок {len(s['wrong'])}"


def tag(q: dict) -> str:
    k = q.get("topic")
    if not k:
        return ""
    if k[0] == "k":
        return f"КП · вопрос программы №{num_of(k)}\n"
    if k[0] == "t":
        return f"ТГП · {TITLES[k]}\n"
    return "КП · дополнительно\n"


def question_text(s: dict) -> str:
    q = s["qs"][s["i"]]
    opts = "\n\n".join(f"{LETTERS[k]}.  {o}" for k, o in enumerate(q["opts"]) if k not in q["hide"])
    return f"{head(s)}\n\n{tag(q)}{q['q']}\n\n{opts}"


def review_text(s: dict, choice: int) -> str:
    q = s["qs"][s["i"]]
    lines = []
    for k, o in enumerate(q["opts"]):
        mark = "✓" if k == q["ans"] else ("✗" if k == choice else "·")
        lines.append(f"{mark} {LETTERS[k]}.  {o}")
    return f"{head(s)}\n\n{tag(q)}{q['q']}\n\n" + "\n\n".join(lines) + f"\n\n{q['expl']}"


def question_kb(s: dict):
    q = s["qs"][s["i"]]
    shown = [k for k in range(len(q["opts"])) if k not in q["hide"]]
    kb = InlineKeyboardBuilder()
    for k in shown:
        kb.button(text=LETTERS[k], callback_data=f"ans:{k}")
    sizes = [len(shown)]
    if not q["hide"] and s["fifty"] > 0:
        kb.button(text=f"50/50 · {s['fifty']}", callback_data="fifty")
        sizes.append(1)
    kb.button(text="Пропустить", callback_data="skip")
    kb.button(text="Выйти", callback_data="quit")
    sizes.append(2)
    kb.adjust(*sizes)
    return kb.as_markup()


