def intro_kb(key: str):
    n = num_of(key)
    total = len(POOLS[key])
    kb = InlineKeyboardBuilder()
    kb.button(text=f"Начать · {total}", callback_data=f"go:{key}:{total}")
    sizes = [1]
    if total > 5:
        kb.button(text="5 случайных", callback_data=f"go:{key}:5")
        sizes[0] = 2
    if n > 1:
        kb.button(text=f"‹ №{n - 1}", callback_data=f"tp:k{n - 1}")
    if n < 30:
        kb.button(text=f"№{n + 1} ›", callback_data=f"tp:k{n + 1}")
    sizes.append((n > 1) + (n < 30))
    kb.button(text="← К разделу", callback_data=back_target(key))
    kb.button(text="Меню", callback_data="menu")
    sizes.append(2)
    kb.adjust(*sizes)
    return kb.as_markup()


def nums_view():
    text = "Вопросы программы\n\n" + "\n".join(f"{n}. {SHORT[n]}" for n in range(1, 31))
    kb = InlineKeyboardBuilder()
    for n in range(1, 31):
        kb.button(text=str(n), callback_data=f"tp:k{n}")
    kb.button(text="← Назад", callback_data="sec:kp")
    kb.adjust(6, 6, 6, 6, 6, 1)
    return text, kb.as_markup()


def stats_view(uid: int):
    st = stats.get(uid, {"tests": 0, "answered": 0, "correct": 0})
    pct = round(st["correct"] / st["answered"] * 100) if st["answered"] else 0
    text = (f"Статистика\n\nТестов пройдено: {st['tests']}\n"
            f"Отвечено вопросов: {st['answered']}\n"
            f"Правильных ответов: {st['correct']} ({pct}%)")
    weak = weak_info(uid)[:3]
    if weak:
        text += "\n\nСлабые темы:\n" + "\n".join(
            f"· {full_title(k)} — {round(p * 100)}% ({c}/{t})" for p, k, c, t in weak)
    kb = InlineKeyboardBuilder()
    if weak:
        kb.button(text="Тренировать слабые темы", callback_data="weak")
    kb.button(text="Сбросить", callback_data="statsreset")
    kb.button(text="← Меню", callback_data="menu")
    if weak:
        kb.adjust(1, 2)
    else:
        kb.adjust(2)
    return text, kb.as_markup()


