# ---------- тест ----------
def need_session(c: CallbackQuery):
    return sessions.get(c.from_user.id)


@dp.callback_query(F.data.startswith("ans:"))
async def answer(c: CallbackQuery):
    s = need_session(c)
    if not s:
        await c.answer("Тест не начат. Нажмите /start", show_alert=True)
        return
    uid = c.from_user.id
    choice = int(c.data.split(":")[1])
    q = s["qs"][s["i"]]
    st = stats.setdefault(uid, {"tests": 0, "answered": 0, "correct": 0})
    ts = tstats.setdefault(uid, {}).setdefault(q["topic"], [0, 0]) if q.get("topic") else None
    st["answered"] += 1
    if ts:
        ts[1] += 1
    if choice == q["ans"]:
        s["score"] += 1
        st["correct"] += 1
        if ts:
            ts[0] += 1
    else:
        s["wrong"].append(q)
    await edit(c, review_text(s, choice), next_kb())
    await c.answer()


@dp.callback_query(F.data == "fifty")
async def fifty(c: CallbackQuery):
    s = need_session(c)
    if not s:
        await c.answer("Тест не начат. Нажмите /start", show_alert=True)
        return
    q = s["qs"][s["i"]]
    if q["hide"] or s["fifty"] <= 0:
        await c.answer("Подсказка недоступна")
        return
    wrong = [k for k in range(len(q["opts"])) if k != q["ans"]]
    q["hide"] = random.sample(wrong, 2)
    s["fifty"] -= 1
    await edit(c, question_text(s), question_kb(s))
    await c.answer("Убрано два неверных ответа")


@dp.callback_query(F.data == "skip")
async def skip(c: CallbackQuery):
    s = need_session(c)
    if not s:
        await c.answer("Тест не начат. Нажмите /start", show_alert=True)
        return
    if len(s["qs"]) - s["i"] <= 1:
        await c.answer("Это последний вопрос", show_alert=True)
        return
    s["qs"].append(s["qs"].pop(s["i"]))
    await edit(c, question_text(s), question_kb(s))
    await c.answer("Вопрос перенесён в конец")


