def result_text(s: dict) -> str:
    total = len(s["qs"])
    pct = round(s["score"] / total * 100)
    if pct >= 90:
        grade = "Отлично"
    elif pct >= 75:
        grade = "Хорошо"
    elif pct >= 60:
        grade = "Удовлетворительно"
    else:
        grade = "Нужно подтянуть"
    text = f"Готово\n\n{s['score']} из {total}  ·  {pct}%\n{grade}"
    if s["wrong"]:
        items = [f"· {q['q']}\n→ {q['opts'][q['ans']]}" for q in s["wrong"]]
        out = text + "\n\nОшибки:\n\n"
        shown = 0
        for it in items:
            if len(out) + len(it) + 2 > 3700:
                break
            out += it + "\n\n"
            shown += 1
        if shown < len(items):
            out += f"…и ещё {len(items) - shown}. Нажмите «Повторить ошибки»."
        text = out.rstrip()
    return text


async def finish(c: CallbackQuery, s: dict):
    uid = c.from_user.id
    last[uid] = {"key": s["key"], "n": len(s["qs"]), "wrong": [q["orig"] for q in s["wrong"]]}
    stats.setdefault(uid, {"tests": 0, "answered": 0, "correct": 0})["tests"] += 1
    sessions.pop(uid, None)
    kb = InlineKeyboardBuilder()
    if s["wrong"]:
        kb.button(text=f"Повторить ошибки · {len(s['wrong'])}", callback_data="retry")
    kb.button(text="Ещё раз", callback_data="again")
    target = back_target(s["key"])
    kb.button(text="← Меню" if target == "menu" else "← Назад", callback_data=target)
    if target != "menu":
        kb.button(text="Меню", callback_data="menu")
    kb.adjust(1)
    await edit(c, result_text(s), kb.as_markup())


@dp.callback_query(F.data == "next")
async def next_question(c: CallbackQuery):
    s = need_session(c)
    if not s:
        await c.answer("Тест не начат. Нажмите /start", show_alert=True)
        return
    s["i"] += 1
    if s["i"] >= len(s["qs"]):
        await finish(c, s)
    else:
        await edit(c, question_text(s), question_kb(s))
    await c.answer()


@dp.callback_query(F.data == "retry")
async def retry(c: CallbackQuery):
    info = last.get(c.from_user.id)
    if not info or not info["wrong"]:
        await c.answer("Нечего повторять", show_alert=True)
        return
    await begin(c, info["key"], info["wrong"])
    await c.answer()


@dp.callback_query(F.data == "again")
async def again(c: CallbackQuery):
    info = last.get(c.from_user.id)
    if not info:
        await c.answer("Нажмите /start", show_alert=True)
        return
    tuples = draw(c.from_user.id, info["key"], info["n"])
    if not tuples:
        await c.answer("Нет слабых тем для повторения", show_alert=True)
        return
    await begin(c, info["key"], tuples)
    await c.answer()


