async def defs_list(c: CallbackQuery):
    key = c.data.split(":")[1]
    items = [f"{t}\n{d}" for t, d in defs_of(key)]
    chunks, cur = [], ""
    for it in items:
        if len(cur) + len(it) + 2 > 3800:
            chunks.append(cur.strip())
            cur = ""
        cur += it + "\n\n"
    chunks.append(cur.strip())
    kb = InlineKeyboardBuilder()
    kb.button(text="← Назад", callback_data=f"dback:{key}")
    kb.button(text="Меню", callback_data="menu")
    kb.adjust(1)
    for idx, ch in enumerate(chunks):
        markup = kb.as_markup() if idx == len(chunks) - 1 else None
        if idx == 0:
            await edit(c, ch, markup)
        else:
            await c.message.answer(ch, reply_markup=markup)
    await c.answer()


def card_text(st: dict, show: bool) -> str:
    term, definition = st["deck"][st["i"]]
    text = f"{st['i'] + 1} / {len(st['deck'])}  ·  знаю {st['known']}\n\n{term}"
    return text + (f"\n\n{definition}" if show else "")


def card_kb(st: dict, show: bool):
    kb = InlineKeyboardBuilder()
